// Applies SQL migrations from ./drizzle (generated by drizzle-kit) in journal order.
import Database from "better-sqlite3";
import fs from "node:fs";
import path from "node:path";

const dbPath =
  process.env.DATABASE_PATH ?? path.join(process.cwd(), "data", "autoauction.db");
const drizzleDir = path.join(process.cwd(), "drizzle");
const journalPath = path.join(drizzleDir, "meta", "_journal.json");

fs.mkdirSync(path.dirname(dbPath), { recursive: true });
const sqlite = new Database(dbPath);
sqlite.pragma("journal_mode = WAL");
sqlite.pragma("foreign_keys = ON");

sqlite.exec(
  `CREATE TABLE IF NOT EXISTS __migrations (
     tag TEXT PRIMARY KEY,
     applied_at INTEGER NOT NULL
   )`,
);

if (!fs.existsSync(journalPath)) {
  console.log("No migrations journal found — run `pnpm db:generate` first.");
  process.exit(0);
}

const journal = JSON.parse(fs.readFileSync(journalPath, "utf8")) as {
  entries: { tag: string; when: number }[];
};

const applied = new Set(
  (sqlite.prepare("SELECT tag FROM __migrations").all() as { tag: string }[]).map(
    (r) => r.tag,
  ),
);

for (const entry of journal.entries) {
  if (applied.has(entry.tag)) continue;
  const sql = fs.readFileSync(
    path.join(drizzleDir, `${entry.tag}.sql`),
    "utf8",
  );
  const run = sqlite.transaction(() => {
    sqlite.exec(sql);
    sqlite
      .prepare("INSERT INTO __migrations (tag, applied_at) VALUES (?, ?)")
      .run(entry.tag, Date.now());
  });
  run();
  console.log(`applied ${entry.tag}`);
}

console.log("Migrations up to date.");
sqlite.close();
